namespace ghidra.app.plugin.core.datamgr.actions;

using ghidra.app.plugin.core.datamgr;
using ghidra.app.plugin.core.datamgr;
using ghidra.app.plugin.core.datamgr.tree;
using ghidra.program.model.data;
using ghidra.util;



using docking;
using docking.action;
using docking.action;
using docking.widgets.tree;
using docking.widgets.tree;

public class SetFavoriteDataTypeAction : ToggleDockingAction {

	public SetFavoriteDataTypeAction(DataTypeManagerPlugin plugin) : base("Set Favorite Data Type", plugin.getName())
    {
		setSelected(false); // make this a checkbox
		setPopupMenuData(new MenuData(new string[] { "Favorite" }, null, "VeryLast"));
		setHelpLocation(new HelpLocation("DataPlugin", "Favorites"));
		setEnabled(true);
	}

	/* @Override */
	public bool isEnabledForContext(ActionContext context) {
		if (!(context is DataTypesActionContext)) {
			return false;
		}

		object contextObject = context.getContextObject();
		GTree gTree = (GTree) contextObject;
		TreePath[] selectionPaths = gTree.getSelectionPaths();
		if (selectionPaths.length == 0) {
			return false;
		}

		foreach (TreePath path in selectionPaths) {
			GTreeNode node = (GTreeNode) path.getLastPathComponent();
			if (!(node is DataTypeNode)) {
				return false;
			}
		}

		bool isFavorite = ((DataTypeNode) selectionPaths[0].getLastPathComponent()).isFavorite();
		foreach (TreePath path in selectionPaths) {
			DataTypeNode dataTypeNode = (DataTypeNode) path.getLastPathComponent();
			if (isFavorite != dataTypeNode.isFavorite()) {
				return false;
			}
		}

		setSelected(isFavorite); // if not enabled, then turn off selection state

		return true;
	}

	/* @Override */
	public void actionPerformed(ActionContext context) {
		GTree gTree = (GTree) context.getContextObject();

		TreePath[] selectionPaths = gTree.getSelectionPaths();
		foreach (TreePath path in selectionPaths) {
			DataTypeNode node = (DataTypeNode) path.getLastPathComponent();
			toggleFavorite(node, isSelected());
		}
	}

	private void toggleFavorite(DataTypeNode node, bool isFavorite) {

		DataType dataType = node.getDataType();
		dataType.getDataTypeManager().setFavorite(dataType, isFavorite);
	}
}
